properties.query:
let windowSize = 90m;
let ApprovedArm = _GetWatchlist('Approved_Arm_Operator_List') | project OperatorId;
// S6: GCS 계정 탈취 (브루트포스)
let S6 =
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'login_failure'
    | summarize FailCount=count(), T1=min(TimeGenerated) by OperatorId
    | where FailCount >= 5;
// S12: 임무 자기승인
let S12 =
    UAVMissionPlan_CL
    | where TimeGenerated > ago(windowSize)
    | where Planner == Approver
    | project T2=TimeGenerated, OperatorId=Planner, MissionId;
// S11: 비인가 무장
let S11 =
    UAVWeapon_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('arm','fire')
    | where OperatorId !in (ApprovedArm)
    | project T3=TimeGenerated, OperatorId, WeaponId;
S6
| join kind=inner (S12) on OperatorId
| where T2 >= T1 and T2 <= T1 + 45m
| join kind=inner (S11) on OperatorId
| where T3 >= T2 and T3 <= T2 + 30m
| extend CampaignType = "C4_계정탈취_임무자기승인_무장"
| extend StepSummary = strcat("S6@", tostring(T1), "(실패:", tostring(FailCount), "회) → S12@", tostring(T2), " → S11@", tostring(T3))
| extend Severity = "High"
| project T1, T2, T3, OperatorId, MissionId, WeaponId, FailCount, CampaignType, StepSummary, Severity
